struct ctl_nbr * nbr_to_ctl ( struct nbr * nbr ) { static struct ctl_nbr nctl ; struct timeval now ; nctl . af = nbr -> ei -> eigrp -> af ; nctl . as = nbr -> ei -> eigrp -> as ; memcpy ( nctl . ifname , nbr -> ei -> iface -> name , sizeof ( nctl . ifname ) ) ; nctl . addr = nbr -> addr ; nctl . hello_holdtime = nbr -> hello_holdtime ; nctl . uptime = now . tv_sec - nbr -> uptime ; return ( & nctl ) ; } 